<template><div><div class="page-title"><div><div class="eyebrow">AUTHORIZED DISCOVERY</div><h2>扫描任务</h2></div><el-button type="primary" @click="openCreate">创建扫描</el-button></div><el-alert title="仅允许对明确授权的实验环境执行扫描" type="warning" show-icon class="section-card"/><div v-loading="loading" class="table-wrap section-card"><el-table :data="scans"><el-table-column prop="task_name" label="名称"/><el-table-column prop="target" label="目标范围"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusLabel(row.status)}}</el-tag><span v-if="row.status==='running'" class="scan-hint">正在执行扫描，请稍候...</span></template></el-table-column><el-table-column prop="scan_type" label="类型"/><el-table-column prop="created_at" label="创建时间"/><el-table-column label="操作" width="280"><template #default="{row}"><el-button link type="primary" @click="detail(row)">详情</el-button><el-button link type="success" :disabled="row.status!=='pending'" @click="start(row)">启动</el-button><el-button link type="danger" :disabled="row.status==='running'" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!scans.length" description="暂无扫描任务"/></div><el-dialog v-model="createVisible" title="创建扫描任务" width="430px"><el-form :model="form" label-width="90px"><el-form-item label="任务名称"><el-input v-model="form.task_name"/></el-form-item><el-form-item label="目标"><el-input v-model="form.target" placeholder="仅填写已授权目标"/></el-form-item><el-form-item label="类型"><el-select v-model="form.scan_type"><el-option label="端口扫描" value="port_scan"/></el-select></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建</el-button></template></el-dialog><el-drawer v-model="detailVisible" title="扫描详情" size="520px"><el-descriptions v-if="selected" :column="1" border><el-descriptions-item label="名称">{{selected.task_name}}</el-descriptions-item><el-descriptions-item label="目标">{{selected.target}}</el-descriptions-item><el-descriptions-item label="状态">{{statusLabel(selected.status)}}</el-descriptions-item><el-descriptions-item label="摘要">{{selected.result_summary||selected.error_message||'暂无结果'}}</el-descriptions-item></el-descriptions><el-divider/><el-table :data="results"><el-table-column prop="result_type" label="结果类型"/><el-table-column prop="ip_address" label="IP"/><el-table-column prop="port" label="端口"/><el-table-column prop="protocol" label="协议"/><el-table-column prop="port_state" label="状态"/><el-table-column prop="service_name" label="服务"/><el-table-column prop="product_name" label="产品"/><el-table-column prop="service_version" label="版本"/><el-table-column prop="normalized_data" label="解析结果"/></el-table></el-drawer></div></template>
<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from "vue"; import { ElMessage, ElMessageBox } from "element-plus"; import client from "../api/client"; import type { Scan, ScanResult } from "../api/types";
const scans=ref<Scan[]>([]),results=ref<ScanResult[]>([]),selected=ref<Scan|null>(null),loading=ref(true),saving=ref(false),createVisible=ref(false),detailVisible=ref(false);const form=reactive({task_name:"",target:"",scan_type:"port_scan"});let pollTimer:ReturnType<typeof setInterval>|undefined;
const statusLabel=(status:string)=>({pending:"等待执行",running:"扫描中",completed:"已完成",failed:"扫描失败"}[status]||status);const statusType=(status:string)=>({pending:"warning",running:"",completed:"success",failed:"danger"}[status]||"info") as "warning"|""|"success"|"danger"|"info";const load=async(quiet=false)=>{if(!quiet)loading.value=true;try{scans.value=(await client.get("/scans")).data;}catch{if(!quiet)scans.value=[];}finally{if(!quiet)loading.value=false;}};const openCreate=()=>{Object.assign(form,{task_name:"",target:"",scan_type:"port_scan"});createVisible.value=true};const create=async()=>{saving.value=true;try{await client.post("/scans",form);ElMessage.success("扫描任务已创建");createVisible.value=false;await load();}catch(error:any){ElMessage.error(error.response?.data?.detail||"创建失败，请确认目标已授权");}finally{saving.value=false;}};const start=async(scan:Scan)=>{try{await client.post(`/scans/${scan.id}/start`);ElMessage.success("扫描已启动");await load();}catch(error:any){const code=error.response?.status,detail=error.response?.data?.detail;ElMessage.error(code===409?"任务已完成或正在执行，不能重复启动":(detail||"启动失败，请检查扫描服务"));}};const remove=async(scan:Scan)=>{try{await ElMessageBox.confirm(`删除任务“${scan.task_name}”及其扫描结果？`,`确认删除`,{type:"warning",confirmButtonText:"删除",cancelButtonText:"取消"});await client.delete(`/scans/${scan.id}`);ElMessage.success("扫描任务已删除");await load();}catch(error:any){if(error==="cancel"||error==="close")return;ElMessage.error(error.response?.data?.detail||"删除失败");}};const detail=async(scan:Scan)=>{try{selected.value=(await client.get(`/scans/${scan.id}`)).data;results.value=(await client.get(`/scans/${scan.id}/results`)).data;detailVisible.value=true;}catch{ElMessage.error("无法读取扫描详情");}};onMounted(async()=>{await load();pollTimer=setInterval(()=>load(true),4000);});onUnmounted(()=>{if(pollTimer)clearInterval(pollTimer);});
</script>
<style scoped>.scan-hint{margin-left:8px;color:#8fa9c2;font-size:12px}</style>
